create or replace function app.import_rows_stock_snapshots(p_organization_id uuid,p_batch_id uuid,p_file_no smallint,p_from_row integer,p_to_row integer)
returns table (item_id uuid, location_id uuid, snapshot_date date, quantity numeric(18,3), allocated_quantity numeric(18,3), unit_cost numeric(18,3), currency char(3))
language sql stable security definer set search_path = '' as $$
select j1.id, j2.id, r.cells[3]::date, r.cells[4]::numeric(18,3), r.cells[5]::numeric(18,3), r.cells[6]::numeric(18,3), r.cells[7]::char(3) from ingest.staged_rows r
left join public.items j1 on j1.organization_id=p_organization_id and j1.code=r.cells[1] left join public.locations j2 on j2.organization_id=p_organization_id and j2.code=r.cells[2]
where r.organization_id=p_organization_id and r.batch_id=p_batch_id and r.file_no=p_file_no and r.row_no between p_from_row and p_to_row;
$$;

create or replace function app.import_merge_stock_snapshots(p_batch_id uuid,p_file_no smallint,p_from_row integer,p_to_row integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_org uuid; v_p boolean[]; v_staged integer; v_updated integer; v_inserted integer; v_missing integer;
begin
 select c.organization_id,c.provided into v_org,v_p from app.import_file_context(p_batch_id,p_file_no,'stock_snapshots') c;
 select count(*)::integer, count(*) filter (where x.item_id is null or x.location_id is null)::integer into v_staged,v_missing from app.import_rows_stock_snapshots(v_org,p_batch_id,p_file_no,p_from_row,p_to_row) x;
 perform app.import_require_resolved(v_missing);
 update public.stock_snapshots t set quantity=case when v_p[4] then x.quantity else t.quantity end,
allocated_quantity=case when v_p[5] then x.allocated_quantity else t.allocated_quantity end,
unit_cost=case when v_p[6] then x.unit_cost else t.unit_cost end,
currency=case when v_p[7] then x.currency else t.currency end from app.import_rows_stock_snapshots(v_org,p_batch_id,p_file_no,p_from_row,p_to_row) x where t.organization_id=v_org and t.item_id=x.item_id and t.location_id=x.location_id and t.snapshot_date=x.snapshot_date and ((v_p[4] and t.quantity is distinct from x.quantity) or (v_p[5] and t.allocated_quantity is distinct from x.allocated_quantity) or (v_p[6] and t.unit_cost is distinct from x.unit_cost) or (v_p[7] and t.currency is distinct from x.currency));
 get diagnostics v_updated = row_count;
 insert into public.stock_snapshots(organization_id,item_id,location_id,snapshot_date,quantity,allocated_quantity,unit_cost,currency)
 select v_org,x.item_id, x.location_id, x.snapshot_date, x.quantity, coalesce(x.allocated_quantity,'0'::numeric(18,3)), x.unit_cost, x.currency from app.import_rows_stock_snapshots(v_org,p_batch_id,p_file_no,p_from_row,p_to_row) x where not exists(select 1 from public.stock_snapshots t where t.organization_id=v_org and t.item_id=x.item_id and t.location_id=x.location_id and t.snapshot_date=x.snapshot_date);
 get diagnostics v_inserted = row_count;
 return app.import_counts(v_staged,v_inserted,v_updated,0,0);
end; $$;

