create or replace function app.import_check_refs(p_batch_id uuid, p_file_no smallint, p_first_row integer, p_last_row integer, p_phase text)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org uuid;
  v_entity text;
  v_columns text[];
  v_missing text[];
  v_lookup_positions smallint[];
  v_lookup_names text[];
  v_lookup_entities text[];
  v_lookup_patterns text[];
  v_window daterange;
  v_detail jsonb := case when p_phase = 'commit' then '{"phase": "commit"}'::jsonb end;
  v_found integer := 0;
  v_n integer;
  v_existing integer;
  v_new integer;
  v_first_day date;
  v_last_day date;
begin
  select f.organization_id, f.entity, f.columns into v_org, v_entity, v_columns
  from public.import_files f
  where f.batch_id = p_batch_id and f.file_no = p_file_no;

  -- Codes that name rows of another entity: distinct values first, then the target's natural-key
  -- index and the staging key index, then back to the rows. Both CTEs are materialized: the
  -- staging table has no useful statistics mid-import, and a planner that believes v holds one row
  -- re-evaluates the distinct lookups once per row of v (19 s for a 20,000-row chunk).
  select array_agg(c.position order by c.position), array_agg(c.name order by c.position),
         array_agg(c.lookup_entity order by c.position), array_agg(c.pattern order by c.position)
    into v_lookup_positions, v_lookup_names, v_lookup_entities, v_lookup_patterns
  from ingest.contract_columns c
  where c.entity = v_entity and c.lookup_entity is not null and c.lookup_entity <> v_entity
    and c.name = any (v_columns);
  with v as materialized (
    select r.row_no, c.name, c.lookup_entity, r.cells[c.position] as code
    from ingest.staged_rows r
    cross join unnest(v_lookup_positions, v_lookup_names, v_lookup_entities, v_lookup_patterns)
      as c(position, name, lookup_entity, pattern)
    where r.organization_id = v_org
      and r.batch_id = p_batch_id
      and r.file_no = p_file_no
      and r.row_no between p_first_row and p_last_row
      and r.cells[c.position] <> ''
      and r.cells[c.position] ~ c.pattern
  ), missing as materialized (
    select d.lookup_entity, d.code
    from (select distinct v.lookup_entity, v.code from v) as d
    where not exists (
        select 1 from ingest.staged_rows p
        where p.batch_id = p_batch_id and p.entity = d.lookup_entity and p.nk = d.code and p.organization_id = v_org)
      and not (case d.lookup_entity
        when 'items' then exists (select 1 from public.items t where t.organization_id = v_org and t.code = d.code)
        when 'locations' then exists (select 1 from public.locations t where t.organization_id = v_org and t.code = d.code)
        when 'brands' then exists (select 1 from public.brands t where t.organization_id = v_org and t.code = d.code)
        when 'suppliers' then exists (select 1 from public.suppliers t where t.organization_id = v_org and t.code = d.code)
        when 'work_calendars' then exists (select 1 from public.work_calendars t where t.organization_id = v_org and t.code = d.code)
        else false
      end)
  )
  insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value, detail)
  select v_org, p_batch_id, p_file_no, v.row_no, v.name, 'unknown_reference', 'error', v.code, v_detail
  from v
  join missing m on m.lookup_entity = v.lookup_entity and m.code = v.code;
  get diagnostics v_n = row_count;
  v_found := v_found + v_n;

  if p_phase = 'stage' then
    if v_entity = 'demand_history' then
      v_window := app.demand_history_window();
    end if;
    with r as (
      select s.row_no, s.cells
      from ingest.staged_rows s
      where s.organization_id = v_org
        and s.batch_id = p_batch_id
        and s.file_no = p_file_no
        and s.row_no between p_first_row and p_last_row
    )
    insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value)
    select v_org, p_batch_id, p_file_no, x.row_no, x.column_name, x.code, 'error', left(x.value, 200)
    from (
      select r.row_no, 'country_code' as column_name, 'scope_exactly_one' as code, coalesce(r.cells[1], '') as value
      from r
      where v_entity = 'holiday_overrides'
        and (coalesce(r.cells[1], '') <> '') = (coalesce(r.cells[2], '') <> '')
      union all
      select r.row_no, 'ends_on', 'end_before_start', r.cells[4]
      from r
      where v_entity = 'holiday_overrides'
        and case when r.cells[3] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[3], 'date')
                  and r.cells[4] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[4], 'date')
                 then r.cells[4]::date < r.cells[3]::date else false end
      union all
      select r.row_no, 'ends_on', 'holiday_too_long', r.cells[4]
      from r
      where v_entity = 'holiday_overrides'
        and case when r.cells[3] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[3], 'date')
                  and r.cells[4] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[4], 'date')
                 then r.cells[4]::date - r.cells[3]::date >= 366 else false end
      union all
      select r.row_no, 'parent_location_code', 'must_differ', r.cells[10]
      from r
      where v_entity = 'locations' and r.cells[10] <> '' and r.cells[10] = r.cells[1]
      union all
      select r.row_no, 'to_location_code', 'must_differ', r.cells[2]
      from r
      where v_entity = 'network_links' and r.cells[1] <> '' and r.cells[1] = r.cells[2]
      union all
      select r.row_no, 'lead_time_days_p90', 'p90_below_p50', r.cells[4]
      from r
      where v_entity = 'network_links'
        and case when r.cells[3] ~ '^-?[0-9]+$' and r.cells[4] ~ '^-?[0-9]+$'
                 then r.cells[4]::numeric < r.cells[3]::numeric else false end
      union all
      select r.row_no, 'freight_cost', 'freight_mismatch', r.cells[6]
      from r
      where v_entity = 'network_links'
        and case r.cells[5]
              when 'none' then coalesce(r.cells[6], '') <> '' or coalesce(r.cells[7], '') <> ''
              when 'per_unit' then coalesce(r.cells[6], '') = '' or coalesce(r.cells[7], '') = ''
              when 'per_shipment' then coalesce(r.cells[6], '') = '' or coalesce(r.cells[7], '') = ''
              else false
            end
      union all
      select r.row_no, 'successor_item_code', 'must_differ', r.cells[2]
      from r
      where v_entity = 'item_supersessions' and r.cells[1] <> '' and r.cells[1] = r.cells[2]
      union all
      select r.row_no, 'alternate_item_code', 'must_differ', r.cells[2]
      from r
      where v_entity = 'item_interchanges' and r.cells[1] <> '' and r.cells[1] = r.cells[2]
      union all
      select r.row_no, 'lead_time_days_p90', 'p90_below_p50', r.cells[7]
      from r
      where v_entity = 'suppliers'
        and case when r.cells[6] ~ '^-?[0-9]+$' and r.cells[7] ~ '^-?[0-9]+$'
                 then r.cells[7]::numeric < r.cells[6]::numeric else false end
      union all
      select r.row_no, 'to_currency', 'must_differ', r.cells[2]
      from r
      where v_entity = 'fx_rates' and r.cells[1] <> '' and r.cells[1] = r.cells[2]
      union all
      select r.row_no, 'demand_date', 'date_outside_history_window', r.cells[3]
      from r
      where v_entity = 'demand_history'
        and case when r.cells[3] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[3], 'date')
                 then not (r.cells[3]::date <@ v_window) else false end
    ) as x;
    get diagnostics v_n = row_count;
    v_found := v_found + v_n;
  end if;

  -- Row rules over effective values: the provided value, else the stored value of the existing
  -- row, else the default a new row gets (observe_public_holidays true; the dates and
  -- lead_time_days_p90 empty). These columns are not column groups, so a file may map one side
  -- only. Both phases run them: a stored value can change between validation and commit, and the
  -- merge would then hit the table's CHECK (23514) instead of reporting the row. An empty cell
  -- means no value; an invalid one takes no part (the cell check reports it). The error names the
  -- rule's column when the file provides it, else the other column the file provides;
  -- detail.stored has the stored values the comparison used. The lateral LIMIT 1 keeps each lookup
  -- an index probe whatever the staging statistics say.
  if v_entity = 'work_calendars'
     or (v_entity = 'items' and v_columns && array['introduced_on', 'discontinued_on'])
     or (v_entity = 'supplier_items' and v_columns && array['lead_time_days', 'lead_time_days_p90']) then
    with r as (
      select s.row_no, s.cells
      from ingest.staged_rows s
      where s.organization_id = v_org
        and s.batch_id = p_batch_id
        and s.file_no = p_file_no
        and s.row_no between p_first_row and p_last_row
    ), y as (
      -- work_calendars: observe_public_holidays needs a country_code
      select x.row_no, 'country_required' as code,
             case when x.country_cell is null and x.observe_cell is not null then 'observe_public_holidays'
                  else 'country_code' end as column_name,
             case when x.country_cell is null and x.observe_cell is not null then x.observe_cell
                  else x.country_cell end as value,
             jsonb_strip_nulls(jsonb_build_object(
               'observe_public_holidays', case when x.observe_cell is null then x.stored_observe end)) as stored
      from (
        select r.row_no, r.cells[4] as country_cell, r.cells[6] as observe_cell,
               t.observe_public_holidays as stored_observe,
               case when r.cells[6] is not null then r.cells[6] = 'true'
                    else coalesce(t.observe_public_holidays, true) end as observing,
               case when r.cells[4] is not null then nullif(r.cells[4], '')
                    else t.country_code::text end as country
        from r
        left join lateral (
          select w.country_code, w.observe_public_holidays
          from public.work_calendars w
          where w.organization_id = v_org and w.code = r.cells[1]
          limit 1
        ) as t on true
        where v_entity = 'work_calendars'
      ) as x
      where x.observing and x.country is null
      union all
      -- items: discontinued_on on or after introduced_on
      select x.row_no, 'end_before_start',
             case when x.end_cell is not null then 'discontinued_on' else 'introduced_on' end,
             case when x.end_cell is not null then x.end_cell else x.start_cell end,
             jsonb_strip_nulls(jsonb_build_object(
               'introduced_on', case when x.start_cell is null then x.stored_start end,
               'discontinued_on', case when x.end_cell is null then x.stored_end end))
      from (
        select r.row_no, r.cells[10] as start_cell, r.cells[11] as end_cell,
               t.introduced_on as stored_start, t.discontinued_on as stored_end,
               case when r.cells[10] is null then t.introduced_on
                    when r.cells[10] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[10], 'date')
                      then r.cells[10]::date end as start_on,
               case when r.cells[11] is null then t.discontinued_on
                    when r.cells[11] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[11], 'date')
                      then r.cells[11]::date end as end_on
        from r
        left join lateral (
          select i.introduced_on, i.discontinued_on
          from public.items i
          where i.organization_id = v_org and i.code = r.cells[1]
          limit 1
        ) as t on true
        where v_entity = 'items' and (r.cells[10] is not null or r.cells[11] is not null)
      ) as x
      where x.end_on < x.start_on
      union all
      -- supplier_items: lead_time_days_p90 empty or at least lead_time_days
      select x.row_no, 'p90_below_p50',
             case when x.p90_cell is not null then 'lead_time_days_p90' else 'lead_time_days' end,
             case when x.p90_cell is not null then x.p90_cell else x.p50_cell end,
             jsonb_strip_nulls(jsonb_build_object(
               'lead_time_days', case when x.p50_cell is null then x.stored_p50 end,
               'lead_time_days_p90', case when x.p90_cell is null then x.stored_p90 end))
      from (
        select r.row_no, r.cells[4] as p50_cell, r.cells[5] as p90_cell,
               t.lead_time_days as stored_p50, t.lead_time_days_p90 as stored_p90,
               case when r.cells[4] is null then t.lead_time_days::numeric
                    when r.cells[4] ~ '^-?[0-9]+$' then r.cells[4]::numeric end as p50,
               case when r.cells[5] is null then t.lead_time_days_p90::numeric
                    when r.cells[5] ~ '^-?[0-9]+$' then r.cells[5]::numeric end as p90
        from r
        left join lateral (
          select si.lead_time_days, si.lead_time_days_p90
          from public.suppliers a
          join public.items b on b.organization_id = a.organization_id and b.code = r.cells[2]
          join public.supplier_items si
            on si.organization_id = a.organization_id and si.supplier_id = a.id and si.item_id = b.id
          where a.organization_id = v_org and a.code = r.cells[1]
          limit 1
        ) as t on true
        where v_entity = 'supplier_items' and (r.cells[4] is not null or r.cells[5] is not null)
      ) as x
      where x.p90 < x.p50
    )
    insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value, detail)
    select v_org, p_batch_id, p_file_no, y.row_no, y.column_name, y.code, 'error', left(y.value, 200),
           nullif(coalesce(v_detail, '{}'::jsonb)
                  || case when y.stored <> '{}'::jsonb then jsonb_build_object('stored', y.stored) else '{}'::jsonb end,
                  '{}'::jsonb)
    from y;
    get diagnostics v_n = row_count;
    v_found := v_found + v_n;
  end if;

  -- Existing keys: rows_new / rows_existing, required_for_new on new keys for every
  -- required-for-new column the file does not provide, and (demand) zero rows for keys that do not
  -- exist, which the merge skips.
  v_missing := array(
    select c.name from ingest.contract_columns c
    where c.entity = v_entity and c.required_for_new and not (c.name = any (v_columns))
    order by c.position);
  if v_entity = 'demand_history' then
    -- One primary-key probe per row, limited to the partitions of the chunk's date range. The
    -- lateral LIMIT 1 keeps it a probe whatever the staging statistics say (a hash join would read
    -- the organization's demand for the whole range).
    if p_phase = 'stage' then
      select min(d.day), max(d.day) into v_first_day, v_last_day
      from (
        select case when r.cells[3] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[3], 'date')
                    then r.cells[3]::date end as day
        from ingest.staged_rows r
        where r.organization_id = v_org and r.batch_id = p_batch_id and r.file_no = p_file_no
          and r.row_no between p_first_row and p_last_row
      ) as d;
      perform app.import_analyze_demand_months(v_first_day, v_last_day);
      with e as materialized (
        select r.row_no, r.cells, d.found is not null as found
        from ingest.staged_rows r
        left join public.items i on i.organization_id = v_org and i.code = r.cells[1]
        left join public.locations l on l.organization_id = v_org and l.code = r.cells[2]
        left join lateral (
          select true as found
          from public.demand_history d
          where d.organization_id = v_org and d.item_id = i.id and d.location_id = l.id
            and d.demand_date = case when r.cells[3] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
                                          and pg_catalog.pg_input_is_valid(r.cells[3], 'date') then r.cells[3]::date end
            and d.demand_date between v_first_day and v_last_day
          limit 1
        ) as d on true
        where r.organization_id = v_org
          and r.batch_id = p_batch_id
          and r.file_no = p_file_no
          and r.row_no between p_first_row and p_last_row
      ), zero as (
        insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value, detail)
        select v_org, p_batch_id, p_file_no, e.row_no, '', 'zero_row_new_key', 'warning', null, null
        from e
        where not e.found
          and coalesce(case when e.cells[4] is null then 0::numeric
                            when e.cells[4] ~ '^[0-9]+(\.[0-9]+)?$' then e.cells[4]::numeric end, -1) = 0
          and coalesce(case when e.cells[5] is null then 0::numeric
                            when e.cells[5] ~ '^[0-9]+(\.[0-9]+)?$' then e.cells[5]::numeric end, -1) = 0
        returning 1
      )
      select count(*) filter (where e.found)::integer, count(*) filter (where not e.found)::integer
        into v_existing, v_new
      from e;
      update public.import_files f
      set rows_new = f.rows_new + v_new, rows_existing = f.rows_existing + v_existing
      where f.batch_id = p_batch_id and f.file_no = p_file_no;
    end if;
  elsif p_phase = 'stage' or cardinality(v_missing) > 0 then
    with e as materialized (
      select r.row_no,
        case v_entity
          when 'work_calendars' then exists (
            select 1 from public.work_calendars t where t.organization_id = v_org and t.code = r.cells[1])
          when 'holiday_overrides' then case
            when r.cells[3] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[3], 'date') then exists (
              select 1 from public.holiday_overrides t
              where t.organization_id = v_org
                and t.starts_on = r.cells[3]::date
                and t.scope_key = case
                  when coalesce(r.cells[1], '') <> '' then 'country:' || r.cells[1]
                  else 'calendar:' || (select w.id::text from public.work_calendars w
                                       where w.organization_id = v_org and w.code = r.cells[2]) end)
            else false end
          when 'locations' then exists (
            select 1 from public.locations t where t.organization_id = v_org and t.code = r.cells[1])
          when 'network_links' then exists (
            select 1
            from public.locations a
            join public.locations b on b.organization_id = a.organization_id and b.code = r.cells[2]
            join public.network_links t
              on t.organization_id = a.organization_id and t.from_location_id = a.id and t.to_location_id = b.id
            where a.organization_id = v_org and a.code = r.cells[1])
          when 'brands' then exists (
            select 1 from public.brands t where t.organization_id = v_org and t.code = r.cells[1])
          when 'items' then exists (
            select 1 from public.items t where t.organization_id = v_org and t.code = r.cells[1])
          when 'item_supersessions' then exists (
            select 1
            from public.items p
            join public.item_supersessions t on t.organization_id = p.organization_id and t.predecessor_item_id = p.id
            where p.organization_id = v_org and p.code = r.cells[1])
          when 'item_interchanges' then exists (
            select 1
            from public.items a
            join public.items b on b.organization_id = a.organization_id and b.code = r.cells[2]
            join public.item_interchanges t
              on t.organization_id = a.organization_id
             and least(t.item_id, t.alternate_item_id) = least(a.id, b.id)
             and greatest(t.item_id, t.alternate_item_id) = greatest(a.id, b.id)
            where a.organization_id = v_org and a.code = r.cells[1])
          when 'suppliers' then exists (
            select 1 from public.suppliers t where t.organization_id = v_org and t.code = r.cells[1])
          when 'supplier_items' then exists (
            select 1
            from public.suppliers a
            join public.items b on b.organization_id = a.organization_id and b.code = r.cells[2]
            join public.supplier_items t
              on t.organization_id = a.organization_id and t.supplier_id = a.id and t.item_id = b.id
            where a.organization_id = v_org and a.code = r.cells[1])
          when 'stock_snapshots' then exists(select 1 from public.stock_snapshots t join public.items j1 on j1.organization_id=t.organization_id and j1.id=t.item_id join public.locations j2 on j2.organization_id=t.organization_id and j2.id=t.location_id where t.organization_id=v_org and j1.code=r.cells[1] and j2.code=r.cells[2] and t.snapshot_date=case when pg_input_is_valid(r.cells[3],'date') then r.cells[3]::date end)
          when 'open_orders' then exists(select 1 from public.open_orders t  where t.organization_id=v_org and t.order_code=r.cells[1] and t.line_code=r.cells[2])
          when 'receipts' then exists(select 1 from public.receipts t  where t.organization_id=v_org and t.receipt_code=r.cells[1] and t.line_code=r.cells[2])
          when 'fx_rates' then case
            when r.cells[1] ~ '^[A-Z]{3}$' and r.cells[2] ~ '^[A-Z]{3}$'
                 and r.cells[3] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[3], 'date') then exists (
              select 1 from public.fx_rates t
              where t.organization_id = v_org
                and least(t.from_currency, t.to_currency) = least(r.cells[1]::char(3), r.cells[2]::char(3))
                and greatest(t.from_currency, t.to_currency) = greatest(r.cells[1]::char(3), r.cells[2]::char(3))
                and t.valid_from = r.cells[3]::date)
            else false end
          else false
        end as found
      from ingest.staged_rows r
      where r.organization_id = v_org
        and r.batch_id = p_batch_id
        and r.file_no = p_file_no
        and r.row_no between p_first_row and p_last_row
    ), rfn as (
      insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value, detail)
      select v_org, p_batch_id, p_file_no, e.row_no, m.name, 'required_for_new', 'error', null, v_detail
      from e
      cross join unnest(v_missing) as m(name)
      where not e.found
      returning 1
    )
    select count(*) filter (where e.found)::integer, count(*) filter (where not e.found)::integer,
           (select count(*)::integer from rfn)
      into v_existing, v_new, v_n
    from e;
    v_found := v_found + v_n;
    if p_phase = 'stage' then
      update public.import_files f
      set rows_new = f.rows_new + v_new, rows_existing = f.rows_existing + v_existing
      where f.batch_id = p_batch_id and f.file_no = p_file_no;
    end if;
  end if;

  return v_found;
end;
$$;

create or replace function app.import_merge_unit(p_batch_id uuid, p_file_no smallint, p_entity text, p_from_row integer, p_to_row integer, p_pass integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  return case p_entity
    when 'work_calendars' then app.import_merge_work_calendars(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'holiday_overrides' then app.import_merge_holiday_overrides(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'locations' then case when p_pass = 2
      then app.import_merge_location_parents(p_batch_id, p_file_no, p_from_row, p_to_row)
      else app.import_merge_locations(p_batch_id, p_file_no, p_from_row, p_to_row) end
    when 'network_links' then app.import_merge_network_links(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'brands' then app.import_merge_brands(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'items' then app.import_merge_items(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'item_supersessions' then app.import_merge_item_supersessions(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'item_interchanges' then app.import_merge_item_interchanges(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'suppliers' then app.import_merge_suppliers(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'supplier_items' then app.import_merge_supplier_items(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'fx_rates' then app.import_merge_fx_rates(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'stock_snapshots' then app.import_merge_stock_snapshots(p_batch_id,p_file_no,p_from_row,p_to_row)
    when 'open_orders' then app.import_merge_open_orders(p_batch_id,p_file_no,p_from_row,p_to_row)
    when 'receipts' then app.import_merge_receipts(p_batch_id,p_file_no,p_from_row,p_to_row)
    when 'demand_history' then app.import_merge_demand_history(p_batch_id, p_file_no, p_from_row, p_to_row)
  end;
end;
$$;

create or replace function app.import_prepare_stats(p_batch_id uuid, p_entities text[])
returns text[]
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_entity text;
  v_reltuples real;
  v_relpages integer;
  v_pages bigint;
  v_modified bigint;
  v_inserted bigint;
  v_counts jsonb;
  v_done text[] := '{}';
  v_skip boolean := coalesce(current_setting('maqdar.import_analyze', true), '') = 'skip_locked';
begin
  select b.counts into v_counts from public.import_batches b where b.id = p_batch_id;
  for v_entity in
    select distinct x from unnest(p_entities) as x
    where x in ('work_calendars', 'holiday_overrides', 'locations', 'network_links', 'brands', 'items', 'item_supersessions',
                'item_interchanges', 'suppliers', 'supplier_items', 'fx_rates', 'stock_snapshots', 'open_orders', 'receipts')
    order by 1
  loop
    select c.reltuples, c.relpages, coalesce(s.n_mod_since_analyze, 0),
           pg_catalog.pg_relation_size(c.oid) / current_setting('block_size')::integer
      into v_reltuples, v_relpages, v_modified, v_pages
    from pg_catalog.pg_class c
    left join pg_catalog.pg_stat_user_tables s on s.relid = c.oid
    where c.oid = pg_catalog.to_regclass('public.' || v_entity);
    v_inserted := coalesce((v_counts -> v_entity ->> 'inserted')::bigint, 0);
    if (v_reltuples <= 0 and v_pages > 0)
       or v_pages > v_relpages * 1.2 + 8
       or v_modified > 0.1 * greatest(v_reltuples, 0)
       or v_inserted > 0.1 * greatest(v_reltuples, 0) then
      if v_skip then
        case v_entity
          when 'work_calendars' then analyze (skip_locked) public.work_calendars;
          when 'holiday_overrides' then analyze (skip_locked) public.holiday_overrides;
          when 'locations' then analyze (skip_locked) public.locations;
          when 'network_links' then analyze (skip_locked) public.network_links;
          when 'brands' then analyze (skip_locked) public.brands;
          when 'items' then analyze (skip_locked) public.items;
          when 'item_supersessions' then analyze (skip_locked) public.item_supersessions;
          when 'item_interchanges' then analyze (skip_locked) public.item_interchanges;
          when 'suppliers' then analyze (skip_locked) public.suppliers;
          when 'supplier_items' then analyze (skip_locked) public.supplier_items;
          when 'stock_snapshots' then analyze public.stock_snapshots;
when 'open_orders' then analyze public.open_orders;
when 'receipts' then analyze public.receipts;
        when 'fx_rates' then analyze (skip_locked) public.fx_rates;
        end case;
      else
        case v_entity
          when 'work_calendars' then analyze public.work_calendars;
          when 'holiday_overrides' then analyze public.holiday_overrides;
          when 'locations' then analyze public.locations;
          when 'network_links' then analyze public.network_links;
          when 'brands' then analyze public.brands;
          when 'items' then analyze public.items;
          when 'item_supersessions' then analyze public.item_supersessions;
          when 'item_interchanges' then analyze public.item_interchanges;
          when 'suppliers' then analyze public.suppliers;
          when 'supplier_items' then analyze public.supplier_items;
          when 'stock_snapshots' then analyze public.stock_snapshots;
when 'open_orders' then analyze public.open_orders;
when 'receipts' then analyze public.receipts;
        when 'fx_rates' then analyze public.fx_rates;
        end case;
      end if;
      v_done := v_done || ('public.' || v_entity);
    end if;
  end loop;
  return v_done;
end;
$$;

create type ingest.api_record_stock_snapshots as (item_code text,location_code text,snapshot_date text,quantity text,allocated_quantity text,unit_cost text,currency text,updated_at text);
revoke all on type ingest.api_record_stock_snapshots from public,anon,authenticated,service_role;
create type ingest.api_record_open_orders as (order_code text,line_code text,item_code text,location_code text,supplier_code text,expected_date text,quantity text,unit_cost text,currency text,status text,updated_at text);
revoke all on type ingest.api_record_open_orders from public,anon,authenticated,service_role;
create type ingest.api_record_receipts as (receipt_code text,line_code text,item_code text,location_code text,supplier_code text,receipt_date text,quantity text,unit_cost text,currency text,updated_at text);
revoke all on type ingest.api_record_receipts from public,anon,authenticated,service_role;
create or replace function public.api_list(
  p_key_hash bytea,
  p_entity text,
  p_after text default null,
  p_limit integer default null,
  p_updated_since timestamptz default null
)
returns json
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org uuid;
  v_key uuid;
  v_limit integer := coalesce(p_limit, 100);
  v_after uuid := '00000000-0000-0000-0000-000000000000';
  v_since timestamptz := p_updated_since;
  v_since_text text := to_char(p_updated_since at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
  v_as_of text := to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
  v_cursor jsonb;
  v_data json;
  v_count integer;
  v_last uuid;
  v_next text;
begin
  select a.organization_id, a.api_key_id into v_org, v_key from app.api_authorize(p_key_hash, case when p_entity in ('stock_snapshots','open_orders','receipts') then 'transactions:read' else 'master_data:read' end) as a;
  if p_entity is null or p_entity = 'demand_history'
     or not exists (select 1 from ingest.contract_entities e where e.entity = p_entity) then
    raise exception using errcode = 'MQ404', message = 'no such resource', hint = 'resource';
  end if;
  if v_limit not between 1 and 1000 then
    raise exception using errcode = 'MQ422', message = 'limit is 1 to 1000', hint = 'limit';
  end if;
  if p_updated_since is not null and not isfinite(p_updated_since) then
    raise exception using errcode = 'MQ422', message = 'updated_since is a finite timestamp', hint = 'updated_since';
  end if;
  if p_after is not null then
    v_cursor := app.api_cursor_decode(p_after, p_entity);
    if not coalesce(
         jsonb_typeof(v_cursor -> 'a') = 'string' and pg_catalog.pg_input_is_valid(v_cursor ->> 'a', 'uuid')
         and jsonb_typeof(v_cursor -> 't') = 'string'
         and (v_cursor ->> 't') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$'
         and pg_catalog.pg_input_is_valid(v_cursor ->> 't', 'timestamptz')
         and v_cursor ? 'u'
         and (jsonb_typeof(v_cursor -> 'u') = 'null'
              or (jsonb_typeof(v_cursor -> 'u') = 'string'
                  and (v_cursor ->> 'u') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$'
                  and pg_catalog.pg_input_is_valid(v_cursor ->> 'u', 'timestamptz'))),
         false) then
      raise exception using errcode = 'MQ422', message = 'invalid cursor', hint = 'cursor';
    end if;
    if (v_cursor ->> 'u')::timestamptz is distinct from p_updated_since then
      raise exception using errcode = 'MQ422', message = 'this cursor belongs to another updated_since', hint = 'cursor';
    end if;
    v_after := (v_cursor ->> 'a')::uuid;
    v_as_of := v_cursor ->> 't';
  end if;

  if p_entity = 'work_calendars' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n <= v_limit), '[]'::json), count(*)::integer,
           (array_agg(x.id) filter (where x.n = v_limit))[1]
      into v_data, v_count, v_last
    from (
      select t.id, row_number() over (order by t.id) as n,
             row(t.code, t.name_en, t.name_ar, t.country_code::text,
                 array(select d.v from unnest(t.weekend_days) as d(v) order by d.v),
                 t.observe_public_holidays, t.is_active,
                 to_char(t.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_work_calendars as rec
      from (
        select w.id, w.code, w.name_en, w.name_ar, w.country_code, w.weekend_days, w.observe_public_holidays, w.is_active, w.updated_at
        from public.work_calendars w
        where w.organization_id = v_org and w.id > v_after and (v_since is null or w.updated_at >= v_since)
        order by w.id
        limit v_limit + 1
      ) as t
    ) as x;
  elsif p_entity = 'holiday_overrides' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n <= v_limit), '[]'::json), count(*)::integer,
           (array_agg(x.id) filter (where x.n = v_limit))[1]
      into v_data, v_count, v_last
    from (
      select t.id, row_number() over (order by t.id) as n,
             row(t.country_code::text, wc.code, t.starts_on, t.ends_on, t.kind, t.name_en, t.name_ar, t.note,
                 to_char(t.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_holiday_overrides as rec
      from (
        select h.id, h.country_code, h.work_calendar_id, h.starts_on, h.ends_on, h.kind, h.name_en, h.name_ar, h.note, h.updated_at
        from public.holiday_overrides h
        where h.organization_id = v_org and h.id > v_after and (v_since is null or h.updated_at >= v_since)
        order by h.id
        limit v_limit + 1
      ) as t
      left join lateral (
        select w.code from public.work_calendars w where w.organization_id = v_org and w.id = t.work_calendar_id
      ) as wc on true
    ) as x;
  elsif p_entity = 'locations' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n <= v_limit), '[]'::json), count(*)::integer,
           (array_agg(x.id) filter (where x.n = v_limit))[1]
      into v_data, v_count, v_last
    from (
      select t.id, row_number() over (order by t.id) as n,
             row(t.code, t.name_en, t.name_ar, t.location_type, t.country_code::text, t.city,
                 trim_scale(t.latitude)::text, trim_scale(t.longitude)::text, t.timezone, p.code, t.is_active, wc.code,
                 to_char(t.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_locations as rec
      from (
        select l.id, l.code, l.name_en, l.name_ar, l.location_type, l.country_code, l.city, l.latitude, l.longitude, l.timezone,
               l.parent_location_id, l.is_active, l.work_calendar_id, l.updated_at
        from public.locations l
        where l.organization_id = v_org and l.id > v_after and (v_since is null or l.updated_at >= v_since)
        order by l.id
        limit v_limit + 1
      ) as t
      left join lateral (
        select pl.code from public.locations pl where pl.organization_id = v_org and pl.id = t.parent_location_id
      ) as p on true
      left join lateral (
        select w.code from public.work_calendars w where w.organization_id = v_org and w.id = t.work_calendar_id
      ) as wc on true
    ) as x;
  elsif p_entity = 'network_links' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n <= v_limit), '[]'::json), count(*)::integer,
           (array_agg(x.id) filter (where x.n = v_limit))[1]
      into v_data, v_count, v_last
    from (
      select t.id, row_number() over (order by t.id) as n,
             row(fl.code, tl.code, t.lead_time_days_p50, t.lead_time_days_p90, t.freight_basis, trim_scale(t.freight_cost)::text,
                 t.currency::text, t.is_active,
                 to_char(t.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_network_links as rec
      from (
        select n.id, n.from_location_id, n.to_location_id, n.lead_time_days_p50, n.lead_time_days_p90, n.freight_basis,
               n.freight_cost, n.currency, n.is_active, n.updated_at
        from public.network_links n
        where n.organization_id = v_org and n.id > v_after and (v_since is null or n.updated_at >= v_since)
        order by n.id
        limit v_limit + 1
      ) as t
      left join lateral (
        select l.code from public.locations l where l.organization_id = v_org and l.id = t.from_location_id
      ) as fl on true
      left join lateral (
        select l.code from public.locations l where l.organization_id = v_org and l.id = t.to_location_id
      ) as tl on true
    ) as x;
  elsif p_entity = 'brands' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n <= v_limit), '[]'::json), count(*)::integer,
           (array_agg(x.id) filter (where x.n = v_limit))[1]
      into v_data, v_count, v_last
    from (
      select t.id, row_number() over (order by t.id) as n,
             row(t.code, t.name_en, t.name_ar, t.brand_type, t.country_of_origin::text, t.is_active,
                 to_char(t.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_brands as rec
      from (
        select b.id, b.code, b.name_en, b.name_ar, b.brand_type, b.country_of_origin, b.is_active, b.updated_at
        from public.brands b
        where b.organization_id = v_org and b.id > v_after and (v_since is null or b.updated_at >= v_since)
        order by b.id
        limit v_limit + 1
      ) as t
    ) as x;
  elsif p_entity = 'items' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n <= v_limit), '[]'::json), count(*)::integer,
           (array_agg(x.id) filter (where x.n = v_limit))[1]
      into v_data, v_count, v_last
    from (
      select t.id, row_number() over (order by t.id) as n,
             row(t.code, t.name_en, t.name_ar, br.code, t.product_group, t.unit_of_measure, trim_scale(t.unit_cost)::text,
                 t.currency::text, t.status, t.introduced_on, t.discontinued_on,
                 to_char(t.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_items as rec
      from (
        select i.id, i.code, i.name_en, i.name_ar, i.brand_id, i.product_group, i.unit_of_measure, i.unit_cost, i.currency,
               i.status, i.introduced_on, i.discontinued_on, i.updated_at
        from public.items i
        where i.organization_id = v_org and i.id > v_after and (v_since is null or i.updated_at >= v_since)
        order by i.id
        limit v_limit + 1
      ) as t
      left join lateral (
        select b.code from public.brands b where b.organization_id = v_org and b.id = t.brand_id
      ) as br on true
    ) as x;
  elsif p_entity = 'item_supersessions' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n <= v_limit), '[]'::json), count(*)::integer,
           (array_agg(x.id) filter (where x.n = v_limit))[1]
      into v_data, v_count, v_last
    from (
      select t.id, row_number() over (order by t.id) as n,
             row(pi.code, si.code, t.effective_on, trim_scale(t.quantity_factor)::text, t.note,
                 to_char(t.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_item_supersessions as rec
      from (
        select s.id, s.predecessor_item_id, s.successor_item_id, s.effective_on, s.quantity_factor, s.note, s.updated_at
        from public.item_supersessions s
        where s.organization_id = v_org and s.id > v_after and (v_since is null or s.updated_at >= v_since)
        order by s.id
        limit v_limit + 1
      ) as t
      left join lateral (
        select i.code from public.items i where i.organization_id = v_org and i.id = t.predecessor_item_id
      ) as pi on true
      left join lateral (
        select i.code from public.items i where i.organization_id = v_org and i.id = t.successor_item_id
      ) as si on true
    ) as x;
  elsif p_entity = 'item_interchanges' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n <= v_limit), '[]'::json), count(*)::integer,
           (array_agg(x.id) filter (where x.n = v_limit))[1]
      into v_data, v_count, v_last
    from (
      select t.id, row_number() over (order by t.id) as n,
             row(ii.code, ai.code, t.direction, t.priority::integer, t.note,
                 to_char(t.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_item_interchanges as rec
      from (
        select c.id, c.item_id, c.alternate_item_id, c.direction, c.priority, c.note, c.updated_at
        from public.item_interchanges c
        where c.organization_id = v_org and c.id > v_after and (v_since is null or c.updated_at >= v_since)
        order by c.id
        limit v_limit + 1
      ) as t
      left join lateral (
        select i.code from public.items i where i.organization_id = v_org and i.id = t.item_id
      ) as ii on true
      left join lateral (
        select i.code from public.items i where i.organization_id = v_org and i.id = t.alternate_item_id
      ) as ai on true
    ) as x;
  elsif p_entity = 'suppliers' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n <= v_limit), '[]'::json), count(*)::integer,
           (array_agg(x.id) filter (where x.n = v_limit))[1]
      into v_data, v_count, v_last
    from (
      select t.id, row_number() over (order by t.id) as n,
             row(t.code, t.name_en, t.name_ar, t.country_code::text, t.currency::text, t.lead_time_days_p50, t.lead_time_days_p90,
                 t.is_active, wc.code,
                 to_char(t.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_suppliers as rec
      from (
        select s.id, s.code, s.name_en, s.name_ar, s.country_code, s.currency, s.lead_time_days_p50, s.lead_time_days_p90,
               s.is_active, s.work_calendar_id, s.updated_at
        from public.suppliers s
        where s.organization_id = v_org and s.id > v_after and (v_since is null or s.updated_at >= v_since)
        order by s.id
        limit v_limit + 1
      ) as t
      left join lateral (
        select w.code from public.work_calendars w where w.organization_id = v_org and w.id = t.work_calendar_id
      ) as wc on true
    ) as x;
  elsif p_entity = 'supplier_items' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n <= v_limit), '[]'::json), count(*)::integer,
           (array_agg(x.id) filter (where x.n = v_limit))[1]
      into v_data, v_count, v_last
    from (
      select t.id, row_number() over (order by t.id) as n,
             row(sp.code, it.code, t.supplier_part_number, t.lead_time_days, t.lead_time_days_p90,
                 trim_scale(t.min_order_quantity)::text, trim_scale(t.pack_size)::text, trim_scale(t.unit_price)::text,
                 t.currency::text, t.is_preferred, t.valid_from,
                 to_char(t.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_supplier_items as rec
      from (
        select si.id, si.supplier_id, si.item_id, si.supplier_part_number, si.lead_time_days, si.lead_time_days_p90,
               si.min_order_quantity, si.pack_size, si.unit_price, si.currency, si.is_preferred, si.valid_from, si.updated_at
        from public.supplier_items si
        where si.organization_id = v_org and si.id > v_after and (v_since is null or si.updated_at >= v_since)
        order by si.id
        limit v_limit + 1
      ) as t
      left join lateral (
        select s.code from public.suppliers s where s.organization_id = v_org and s.id = t.supplier_id
      ) as sp on true
      left join lateral (
        select i.code from public.items i where i.organization_id = v_org and i.id = t.item_id
      ) as it on true
    ) as x;
  elsif p_entity = 'stock_snapshots' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n<=v_limit),'[]'::json),count(*)::integer,(array_agg(x.id) filter(where x.n=v_limit))[1]
    into v_data,v_count,v_last from (
      select t.id,row_number() over(order by t.id) as n,row(j1.code,j2.code,t.snapshot_date::text,t.quantity::text,t.allocated_quantity::text,t.unit_cost::text,t.currency::text,to_char(t.updated_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_stock_snapshots as rec
      from (select * from public.stock_snapshots where organization_id=v_org and id>v_after and (v_since is null or updated_at>=v_since) order by id limit v_limit+1) t
      join public.items j1 on j1.organization_id=t.organization_id and j1.id=t.item_id join public.locations j2 on j2.organization_id=t.organization_id and j2.id=t.location_id
    ) x;
  elsif p_entity = 'open_orders' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n<=v_limit),'[]'::json),count(*)::integer,(array_agg(x.id) filter(where x.n=v_limit))[1]
    into v_data,v_count,v_last from (
      select t.id,row_number() over(order by t.id) as n,row(t.order_code::text,t.line_code::text,j3.code,j4.code,j5.code,t.expected_date::text,t.quantity::text,t.unit_cost::text,t.currency::text,t.status::text,to_char(t.updated_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_open_orders as rec
      from (select * from public.open_orders where organization_id=v_org and id>v_after and (v_since is null or updated_at>=v_since) order by id limit v_limit+1) t
      join public.items j3 on j3.organization_id=t.organization_id and j3.id=t.item_id join public.locations j4 on j4.organization_id=t.organization_id and j4.id=t.location_id join public.suppliers j5 on j5.organization_id=t.organization_id and j5.id=t.supplier_id
    ) x;
  elsif p_entity = 'receipts' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n<=v_limit),'[]'::json),count(*)::integer,(array_agg(x.id) filter(where x.n=v_limit))[1]
    into v_data,v_count,v_last from (
      select t.id,row_number() over(order by t.id) as n,row(t.receipt_code::text,t.line_code::text,j3.code,j4.code,j5.code,t.receipt_date::text,t.quantity::text,t.unit_cost::text,t.currency::text,to_char(t.updated_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_receipts as rec
      from (select * from public.receipts where organization_id=v_org and id>v_after and (v_since is null or updated_at>=v_since) order by id limit v_limit+1) t
      join public.items j3 on j3.organization_id=t.organization_id and j3.id=t.item_id join public.locations j4 on j4.organization_id=t.organization_id and j4.id=t.location_id join public.suppliers j5 on j5.organization_id=t.organization_id and j5.id=t.supplier_id
    ) x;
  elsif p_entity = 'fx_rates' then
    select coalesce(json_agg(x.rec order by x.n) filter (where x.n <= v_limit), '[]'::json), count(*)::integer,
           (array_agg(x.id) filter (where x.n = v_limit))[1]
      into v_data, v_count, v_last
    from (
      select t.id, row_number() over (order by t.id) as n,
             row(t.from_currency::text, t.to_currency::text, t.valid_from, trim_scale(t.rate)::text, t.note,
                 to_char(t.updated_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::ingest.api_record_fx_rates as rec
      from (
        select f.id, f.from_currency, f.to_currency, f.valid_from, f.rate, f.note, f.updated_at
        from public.fx_rates f
        where f.organization_id = v_org and f.id > v_after and (v_since is null or f.updated_at >= v_since)
        order by f.id
        limit v_limit + 1
      ) as t
    ) as x;
  end if;

  if v_count > v_limit then
    v_next := app.api_cursor_encode(jsonb_build_object('v', 1, 'k', p_entity, 'a', v_last, 'u', v_since_text, 't', v_as_of));
  end if;
  return json_build_object('data', v_data, 'next_cursor', v_next, 'as_of', v_as_of);
end;
$$;

create or replace function public.api_upsert(p_key_hash bytea, p_entity text, p_body jsonb, p_request_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org uuid;
  v_key uuid;
  v_columns text[];
  v_n integer;
  v_batch uuid := gen_random_uuid();
  v_file_no constant smallint := 1;
  v_sha bytea;
  v_errors integer;
  v_commit jsonb;
  v_counts jsonb;
  v_result jsonb;
  v_constraint text;
  v_analyze text;
begin
  if p_entity is null or not exists (select 1 from ingest.contract_entities e where e.entity = p_entity) then
    raise exception using errcode = 'MQ404', message = 'no such resource', hint = 'resource';
  end if;
  select a.organization_id, a.api_key_id into v_org, v_key
  from app.api_authorize(p_key_hash, case when p_entity in ('demand_history','stock_snapshots','open_orders','receipts') then 'transactions:write' else 'master_data:write' end) as a;
  if p_request_id is null then
    raise exception using errcode = 'MQ422', message = 'a request id is required', hint = 'request_id';
  end if;

  v_columns := app.api_check_fields(p_entity, p_body);
  v_n := jsonb_array_length(p_body -> 'records');

  -- The 5a import lock: one writer per organization, refused at once rather than waited for. It is
  -- taken here, outside the block below, because a lock taken in a rolled-back subtransaction is
  -- released with it.
  if not pg_try_advisory_xact_lock(hashtextextended('maqdar.import:' || v_org::text, 0)) then
    raise exception using errcode = 'MQ409', message = 'another import is writing to this organization; try again shortly',
      hint = 'import_in_progress';
  end if;
  perform app.import_sweep(0);
  delete from ingest.api_writes w
  where w.organization_id = v_org and w.created_at <= now() - interval '24 hours';
  if (select count(*) from (select 1 from ingest.api_writes w
                            where w.organization_id = v_org and w.created_at > now() - interval '24 hours'
                            limit 5000) as x) >= 5000 then
    raise exception using errcode = 'MQ429', message = 'too many recorded API writes in the last 24 hours (at most 5,000)',
      hint = 'api_writes_per_day';
  end if;

  -- ANALYZE (SKIP_LOCKED) in the 5a statistics helpers for this write only. A function SET clause
  -- cannot name a custom setting unless the owner is a superuser (postgres is not, locally or
  -- hosted), so it is set for the transaction here and restored below; an error rolls it back.
  v_analyze := current_setting('maqdar.import_analyze', true);
  perform set_config('maqdar.import_analyze', 'skip_locked', true);

  -- Everything below is undone when the write fails or changes nothing (MQ499 is internal: raised
  -- and caught here only). v_result survives the rollback.
  begin
    v_sha := sha256(convert_to(p_body::text, 'UTF8'));
    begin
      insert into public.import_batches (id, organization_id, source, status, commit_mode, created_by, api_key_id, api_request_id,
                                         files_sha256, file_count, rows_total, validated_at, commit_started_at, last_step_at,
                                         expires_at)
      values (v_batch, v_org, 'api', 'committing', 'atomic', null, v_key, p_request_id,
              v_sha, 1, v_n, now(), now(), now(), null);
    exception when unique_violation then
      get stacked diagnostics v_constraint = constraint_name;
      if v_constraint = 'import_batches_one_committing' then
        raise exception using errcode = 'MQ409', message = 'another import of this organization is committing',
          hint = 'another_commit';
      end if;
      raise;
    end;
    insert into public.import_files (organization_id, batch_id, file_no, entity, original_name, content_type, extension,
                                     size_bytes, sha256, storage_path, columns, rows_total)
    values (v_org, v_batch, v_file_no, p_entity, 'POST /api/v1/' || replace(p_entity, '_', '-') || ':upsert', 'application/json',
            'json', octet_length(p_body::text), v_sha, v_org::text || '/' || v_batch::text || '/1.json', v_columns, v_n);

    -- import_stage_chunk's order: stage, statistics of the entity and its lookups, cells,
    -- references and row rules; then import_seal_file's set rules.
    perform app.api_stage_records(v_batch, p_body -> 'records');
    perform app.import_prepare_stats(v_batch, array(
      select p_entity
      union
      select c.lookup_entity from ingest.contract_columns c where c.entity = p_entity and c.lookup_entity is not null));
    perform app.import_check_cells(v_batch, v_file_no, 1, v_n);
    perform app.import_check_refs(v_batch, v_file_no, 1, v_n, 'stage');
    perform app.import_flush_errors(v_batch, v_file_no);
    perform app.import_check_sets(v_batch, v_file_no);
    perform app.import_flush_errors(v_batch, v_file_no);
    update public.import_files f set status = 'sealed', sealed_at = now()
    where f.organization_id = v_org and f.batch_id = v_batch and f.file_no = v_file_no;

    select b.error_count into v_errors from public.import_batches b where b.id = v_batch;
    if v_errors > 0 then
      v_result := app.api_error_result(v_batch, 'invalid');
      raise exception using errcode = 'MQ499', message = 'api write rolled back';
    end if;

    v_commit := app.import_commit_atomic(v_batch);
    if v_commit ->> 'failure_code' is not null then
      v_result := app.api_error_result(v_batch, 'conflict');
      raise exception using errcode = 'MQ499', message = 'api write rolled back';
    end if;

    select b.counts -> p_entity into v_counts from public.import_batches b where b.id = v_batch;
    if coalesce((v_counts ->> 'inserted')::bigint, 0) + coalesce((v_counts ->> 'updated')::bigint, 0)
       + coalesce((v_counts ->> 'deleted')::bigint, 0) + coalesce((v_counts ->> 'parents_set')::bigint, 0)
       + coalesce((v_counts ->> 'preferred_cleared')::bigint, 0) = 0 then
      v_result := app.api_success_result(v_batch, false);
      raise exception using errcode = 'MQ499', message = 'api write rolled back';
    end if;
    -- In the same transaction as the data; failures and no-ops never reach this insert.
    insert into ingest.api_writes (organization_id, batch_id) values (v_org, v_batch);
    v_result := app.api_success_result(v_batch, true);
  exception when sqlstate 'MQ499' then
    null;
  end;
  perform set_config('maqdar.import_analyze', coalesce(v_analyze, ''), true);
  return v_result;
end;
$$;

do $$ declare f regprocedure; begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='app' and (p.proname like 'import_rows_%' or p.proname like 'import_merge_%') loop
 execute format('revoke all on function %s from public,anon,authenticated,service_role',f);
 end loop;
end $$;
reset lock_timeout;
